import{_ as t,o as e,c as o,a5 as p}from"./chunks/framework.Cooo9kuv.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"IM001-将指定文件夹下所有图片拼接成为一个长图","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["图片批处理"],"标签":["图片合并为长图","批量图片合并","批量图片合并长图","长图拼接","长图生成"]},"headers":[],"relativePath":"md/图片批处理/IM001-将指定文件夹下所有图片拼接成为一个长图.md","filePath":"md/图片批处理/IM001-将指定文件夹下所有图片拼接成为一个长图.md"}'),n={name:"md/图片批处理/IM001-将指定文件夹下所有图片拼接成为一个长图.md"};function r(s,a,_,m,c,g){return e(),o("div",null,[...a[0]||(a[0]=[p('<p>批量将指定文件夹下所有图片拼接为一个长图</p><p>比如A文件夹下有很多的图片，只需要将A文件夹拖入到程序中或复制A文件夹路径到程序中即可，可指定哪些扩展名图片合并为一张长图。</p><p>建议在拼接长图前统一图片尺寸宽度，宽度一样的情况下拼接的长图更好看些。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250224140209174037692960511.png" alt=""></p><h3 id="程序截图" tabindex="-1">程序截图 <a class="header-anchor" href="#程序截图" aria-label="Permalink to &quot;程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250224143016174037861692590.png" alt=""></p><p>输入图片格式部分可以不输入，不输入则对所有图片格式进行合并，如果指定则只对指定的图片格式进行操作合并为长图。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250224142815174037849564548.png" alt=""></p><h3 id="imagemagick安装方式" tabindex="-1">ImageMagick安装方式 <a class="header-anchor" href="#imagemagick安装方式" aria-label="Permalink to &quot;ImageMagick安装方式&quot;">​</a></h3><p>先在电脑D盘创建文件夹：ImageMagick  然后将其安装在这个文件夹内</p><p>如果电脑没有D盘则在C盘按照此方式创建文件夹安装</p><p>如果你是win32位操作系统则使用32位的程序（X86）安装，如果是64位操作系统则按照64位的程序（X64）安装</p><p><strong>ImageMagick下载：</strong></p><p>通过网盘分享的文件：ImageMagick安装（必须安装此工具）<br> 链接: <a href="https://pan.baidu.com/s/12cRu46eo0m0xOFZP_aLt2A?pwd=myti" target="_blank" rel="noreferrer">https://pan.baidu.com/s/12cRu46eo0m0xOFZP_aLt2A?pwd=myti</a> 提取码: myti</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1472.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1472.html</a></p>',16)])])}const d=t(n,[["render",r]]);export{l as __pageData,d as default};
